// gen-confusables downloads the Unicode UTR #39 confusables.txt data file
// and generates a Go map[rune]string for homoglyph normalization at build time.
//
// Usage: go run scripts/gen-confusables.go
//
// The generated file is written to mailserver/internal/smtp/confusables.go.
// Run via go:generate from the antiphish package.
package main

import (
	"bufio"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

const (
	confusablesURL = "https://www.unicode.org/Public/security/latest/confusables.txt"
	outputFile     = "setjoin.com/mailserver/internal/smtp/confusables.go"
)

func main() {
	resp, err := http.Get(confusablesURL)
	if err != nil {
		fmt.Fprintf(os.Stderr, "gen-confusables: failed to download confusables.txt: %v\n", err)
		os.Exit(1)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		fmt.Fprintf(os.Stderr, "gen-confusables: HTTP %d from unicode.org\n", resp.StatusCode)
		os.Exit(1)
	}

	confusables, err := parseConfusables(resp.Body)
	if err != nil {
		fmt.Fprintf(os.Stderr, "gen-confusables: parse error: %v\n", err)
		os.Exit(1)
	}

	if err := writeGoMap(confusables); err != nil {
		fmt.Fprintf(os.Stderr, "gen-confusables: failed to write output: %v\n", err)
		os.Exit(1)
	}

	fmt.Printf("gen-confusables: wrote %d homoglyph mappings to %s\n", len(confusables), outputFile)
}

// parseConfusables reads UTR #39 confusables.txt and extracts
// homoglyph → ASCII mappings (MA type only).
func parseConfusables(r io.Reader) (map[rune]string, error) {
	out := make(map[rune]string)
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())

		// Skip comments and empty lines
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}

		// Format: <source> ; <target> ; <type> # comment
		// Example: 1D0F ;	006F ;	MA	# ( ὏ → o ) ...
		parts := strings.Split(line, ";")
		if len(parts) < 3 {
			continue
		}

		typ := strings.TrimSpace(parts[2])
		if typ != "MA" {
			continue // only care about homoglyph mappings
		}

		srcHex := strings.TrimSpace(parts[0])
		tgtHex := strings.TrimSpace(parts[1])

		srcRune, err := parseHexRune(srcHex)
		if err != nil {
			continue
		}
		tgtRunes, err := parseHexRunes(tgtHex)
		if err != nil || len(tgtRunes) == 0 {
			continue
		}

		// Only include if target is pure ASCII (replacement is single-byte printable char)
		targetStr := string(tgtRunes)
		if isAllASCII(targetStr) {
			out[srcRune] = targetStr
		}
	}
	return out, scanner.Err()
}

// parseHexRune parses a single hex codepoint like "006F".
func parseHexRune(hex string) (rune, error) {
	v, err := strconv.ParseUint(hex, 16, 32)
	if err != nil {
		return 0, err
	}
	return rune(v), nil
}

// parseHexRunes parses a space-separated sequence of hex codepoints like "006F 0074".
func parseHexRunes(hex string) ([]rune, error) {
	parts := strings.Fields(hex)
	runes := make([]rune, 0, len(parts))
	for _, p := range parts {
		r, err := parseHexRune(p)
		if err != nil {
			return nil, err
		}
		runes = append(runes, r)
	}
	return runes, nil
}

func isAllASCII(s string) bool {
	for _, r := range s {
		if r > 127 {
			return false
		}
	}
	return true
}

// writeGoMap writes the confusables map as a Go source file.
func writeGoMap(confusables map[rune]string) error {
	// Resolve output path relative to the repo root (where go:generate runs).
	// go:generate runs in the package directory, so the output path is relative to
	// mailserver/internal/smtp/. We resolve from the working directory
	// which is typically the repo root.
	absOutput := outputFile
	if !filepath.IsAbs(outputFile) {
		// Find the repo root by walking upward
		dir, err := os.Getwd()
		if err != nil {
			return fmt.Errorf("getwd: %w", err)
		}
		absOutput = filepath.Join(dir, outputFile)
	}

	f, err := os.Create(absOutput)
	if err != nil {
		return fmt.Errorf("create: %w", err)
	}
	defer f.Close()

	fmt.Fprintf(f, `// Code generated by gen-confusables.go DO NOT EDIT.
// Unicode UTR #39 confusables: homoglyph → ASCII mappings for lookalike domain detection.

package smtp

// Confusables maps Unicode homoglyph runes to their ASCII equivalents.
// Source: Unicode UTR #39 (https://www.unicode.org/Public/security/latest/confusables.txt).
// Generated at build time via go:generate.
var Confusables = map[rune]string{
`)

	// Sort by key for deterministic output (optional but nice for diffs)
	for src, tgt := range confusables {
		fmt.Fprintf(f, "\t0x%04X: %q, // %c → %s\n", src, tgt, src, tgt)
	}

	fmt.Fprintf(f, "}\n")
	return nil
}
